import {compileHandoff} from '/home/holo/line/scripts/v0/optimizer/handoff.ts';
const root='/tmp/engine-next-20261105';
const cellIndex=Number(process.argv[2]), profiling=process.argv.includes('--profile');
const cell=JSON.parse(readFileSync('/home/holo/line/tools/parity/cells.json','utf8')).cells[cellIndex];
const catalog=loadCatalog(), c=catalog.cases.find(c=>c.id===cell.id)!, music=catalog.music.find(m=>m.id===c.sourceId)!;
const requested=c.plans[cell.seed], spec=caseSpec(music);
const contracts={strike:'line.strike.v1',strike2:'line.strike.v2',strike3:'line.strike.v3'};
const options={budget:cell.budget??policy.budget, ...(contracts[cell.mode]?{impactContract:contracts[cell.mode]}:{}),
  ...(c.panel==='automatic'?{creative:requested.preferences}:{constructionPlan:requested})};
const profiler=new Session();
if(profiling){profiler.connect(); await profiler.post('Profiler.enable'); await profiler.post('Profiler.setSamplingInterval',{interval:250});}
const iterations=[];
for(let rep=-5;rep<3;rep++){
 if(profiling&&rep>=0) await profiler.post('Profiler.start');
 const cpu=process.cpuUsage(),start=performance.now();
 const checkpoint=compileHandoff(spec,cell.seed,options);
 const wallMs=performance.now()-start,used=process.cpuUsage(cpu);
 if(profiling&&rep>=0){const {profile}=await profiler.post('Profiler.stop');writeFileSync(`${root}/cell-${cellIndex}-${rep}.cpuprofile`,JSON.stringify(profile));}
 const trackHash=createHash('sha256').update(JSON.stringify(checkpoint.track)).digest('hex');
 assert.equal(trackHash,cell.trackHash);assert.equal(checkpoint.stats.sim_frames,cell.physicalFrames);
 iterations.push({rep,wallMs,cpuMs:(used.user+used.system)/1000,nsPerFrame:wallMs*1e6/cell.physicalFrames,physicalFrames:cell.physicalFrames,trackHash});
}
if(profiling)profiler.disconnect();
writeFileSync(`${root}/${profiling?'profile':'baseline'}-${cellIndex}.json`,JSON.stringify({cell:cellIndex,profiling,node:process.version,iterations},null,2));
console.log(`Finished ${profiling?'profile':'baseline'} cell ${cellIndex}; exact track/work throughout`);

